'use client';
import {useEffect,useRef,useState} from 'react';
import {hotelClient} from '@/lib/pilot';
import {PrepareTestPayment} from '@/components/prepare-test-payment';
type ArrivalDetails={name:string;phone:string;email?:string;arrivalTime:string;address_line1?:string;address_line2?:string;city?:string;region?:string;postal_code?:string;country_code?:string};
type CommunicationWithdrawal={purpose:'operational'|'marketing';channel:'email'|'sms';actor:string;recorded_at:number};
type CommunicationPreferences={notice_version:string;operational_email:number;operational_sms:number;marketing_email:number;marketing_sms:number;recorded_at:number;source:string;withdrawals?:CommunicationWithdrawal[]};
type RecordState={expires_at:number;submitted_at:number|null;details:ArrivalDetails|null;communications?:CommunicationPreferences|null};
function validCommunicationPreferences(value:unknown):value is CommunicationPreferences{if(!value||typeof value!=='object'||Array.isArray(value))return false;const c=value as Partial<CommunicationPreferences>;return c.notice_version==='guest-arrival-v1'&&[c.operational_email,c.operational_sms,c.marketing_email,c.marketing_sms].every(flag=>flag===0||flag===1)&&Number.isSafeInteger(c.recorded_at)&&Number(c.recorded_at)>0&&c.source==='guest_precheck'&&(c.withdrawals===undefined||(Array.isArray(c.withdrawals)&&c.withdrawals.every(w=>!!w&&['operational','marketing'].includes(w.purpose)&&['email','sms'].includes(w.channel)&&typeof w.actor==='string'&&/^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$/i.test(w.actor)&&Number.isSafeInteger(w.recorded_at)&&w.recorded_at>0)))}
type PrecheckRequestContext={actor:string;tenant:string;property:string;reservation:string};
async function requestPrecheck(action:string,context:PrecheckRequestContext,requests:Set<AbortController>,extra:Record<string,unknown>={}){
 const {actor,tenant,property,reservation}=context,controller=new AbortController();requests.add(controller);let onAbort:()=>void=()=>{};const interrupted=new Promise<never>((_,reject)=>{onAbort=()=>reject(Error('Arrival screen closed. Reopen the reservation to check the saved status.'));controller.signal.addEventListener('abort',onAbort,{once:true})});let timer:ReturnType<typeof setTimeout>|undefined;
 try{return await Promise.race([interrupted,(async()=>{
  const {data}=await hotelClient().auth.getSession();if(controller.signal.aborted)throw Error('Request timed out.');if(!data.session)throw Error('Sign in again.');if(!actor||data.session.user?.id!==actor)throw Error('Your account changed. Reopen the reservation before continuing.');
  const response=await fetch('/api/precheck',{method:'POST',signal:controller.signal,headers:{'Content-Type':'application/json',Authorization:'Bearer '+data.session.access_token},body:JSON.stringify({action,tenant,property,reservation,...extra})});
  const result=await response.json() as {error?:string;record:RecordState|null;token:string;revoked?:boolean;withdrawn?:boolean;alreadyRecorded?:boolean};if(!response.ok)throw Error(result?.error||'Please retry.');
  const record=result?.record,details=record?.details,optional=['address_line1','address_line2','city','region','postal_code','country_code'] as const;
  const invalidDetails=details!==null&&details!==undefined&&(!details||typeof details.name!=='string'||typeof details.phone!=='string'||typeof details.arrivalTime!=='string'||optional.some(key=>details[key]!==undefined&&typeof details[key]!=='string'));
  const communication=record?.communications,invalidCommunication=communication!==undefined&&communication!==null&&!validCommunicationPreferences(communication);
  const invalidRead=record===undefined||(record!==null&&(!Number.isSafeInteger(record.expires_at)||record.expires_at<0||(record.submitted_at!==null&&!Number.isSafeInteger(record.submitted_at))||invalidDetails||invalidCommunication));
  const invalid=!result||typeof result!=='object'||Array.isArray(result)||(action==='staff_issue'&&(typeof result.token!=='string'||!/^[a-f0-9]{64}$/.test(result.token)))||(action==='staff_revoke'&&result.revoked!==true)||(action==='staff_withdraw_communication'&&result.withdrawn!==true)||(action==='staff_read'&&invalidRead);
  if(invalid)throw Error('Arrival result could not be confirmed. Refresh details before trying another change.');return result;
 })(),new Promise<never>((_,reject)=>{timer=setTimeout(()=>{reject(Error('Arrival-link request is not confirmed. Select Refresh details to check before trying another change.'));controller.abort()},30000)})])}finally{clearTimeout(timer);controller.signal.removeEventListener('abort',onAbort);requests.delete(controller);controller.abort()}
}
export function PrecheckPanel({actor,tenant,property,reservation,disabled,canCancelPayment=false}:{actor:string;tenant:string;property:string;reservation:string;disabled:boolean;canCancelPayment?:boolean}){
 const actionPending=useRef(false),readSequence=useRef(0),requests=useRef(new Set<AbortController>());
 const [record,setRecord]=useState<RecordState|null>(null),[link,setLink]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState(''),[loaded,setLoaded]=useState(false),[copied,setCopied]=useState(false);

 useEffect(()=>{let live=true;const sequenceRef=readSequence,activeRequests=requests.current,sequence=++sequenceRef.current;requestPrecheck('staff_read',{actor,tenant,property,reservation},activeRequests).then(d=>{if(live&&sequence===sequenceRef.current){setRecord(d.record);setLoaded(true)}}).catch(e=>{if(live&&sequence===sequenceRef.current)setError(e instanceof Error?e.message:'Please retry.')});return()=>{live=false;sequenceRef.current++;for(const controller of activeRequests)controller.abort();activeRequests.clear()}},[actor,tenant,property,reservation]);
 async function run(action:string,extra:Record<string,unknown>={}){if(actionPending.current||disabled)return;actionPending.current=true;const sequence=++readSequence.current;setBusy(true);setError('');setCopied(false);try{const d=await requestPrecheck(action,{actor,tenant,property,reservation},requests.current,extra);if(sequence!==readSequence.current)return;if(action==='staff_issue')setLink(`${window.location.origin}/precheck#token=${d.token}`);if(action==='staff_revoke')setLink('');const latest=action==='staff_read'?d:await requestPrecheck('staff_read',{actor,tenant,property,reservation},requests.current);if(sequence!==readSequence.current)return;setRecord(latest.record);setLoaded(true)}catch(e){if(sequence===readSequence.current)setError(e instanceof Error?e.message:'Please retry.')}finally{actionPending.current=false;if(sequence===readSequence.current)setBusy(false)}}
 function recordCommunicationWithdrawal(purpose:'operational'|'marketing',channel:'email'|'sms'){const label=(purpose==='marketing'?'promotional ':'stay-related ')+(channel==='email'?'email':'text');if(!window.confirm('Record the guest’s request to stop '+label+' messages for this reservation?'))return;void run('staff_withdraw_communication',{purpose,channel,requestId:crypto.randomUUID()})}
 function communicationChoice(purpose:'operational'|'marketing',channel:'email'|'sms'){const c=record?.communications;if(!c)return null;const flag=purpose==='operational'?(channel==='email'?c.operational_email:c.operational_sms):(channel==='email'?c.marketing_email:c.marketing_sms);const withdrawal=(c.withdrawals??[]).find(w=>w.purpose===purpose&&w.channel===channel);return {optedIn:flag===1,withdrawal}}
 async function copyKioskLink(){if(!link)return;const url=new URL(link);url.searchParams.set('mode','kiosk');try{await navigator.clipboard.writeText(url.toString());setCopied(true)}catch{setError('Select and copy the guest link, then add ?mode=kiosk before the #token section.')}}
 const address=record?.details?[record.details.address_line1,record.details.address_line2,[record.details.city,record.details.region,record.details.postal_code].filter(Boolean).join(', '),record.details.country_code].filter(Boolean).join(' · '):'';
 return <section className="precheck-staff"><h3>Phone pre-check-in</h3>{error&&<p role="alert" className="pilot-error">{error}</p>}{record?.details?<div><b>Arrival details received</b><p>{record.details.name} · {record.details.phone}{record.details.email?` · ${record.details.email}`:''}</p><p>Estimated arrival: {record.details.arrivalTime} (property time)</p>{address&&<p>Mailing address: {address}</p>}<small>Guest supplied details. Review them against the reservation and ID before check-in. Identity-document numbers and images are not collected by this form.</small></div>:<p>{loaded?'No arrival details received yet.':'Loading arrival details…'}</p>}{record?.communications&&<section className="precheck-consents" aria-label="Guest communication preferences"><h4>Guest communication choices</h4><dl>{([['operational','email','Stay updates by email'],['operational','sms','Stay updates by text'],['marketing','email','Promotional email'],['marketing','sms','Promotional text']] as const).map(([purpose,channel,label])=>{const choice=communicationChoice(purpose,channel);return <div key={purpose+channel}><dt>{label}</dt><dd>{choice?.withdrawal?'Withdrawn':choice?.optedIn?'Opted in':'Not opted in'}{choice?.optedIn&&!choice.withdrawal&&<button type="button" className="text-button" disabled={busy||disabled} onClick={()=>recordCommunicationWithdrawal(purpose,channel)}>Record guest request</button>}{choice?.withdrawal&&<small>Withdrawn {new Date(choice.withdrawal.recorded_at).toLocaleString()} · Staff account {choice.withdrawal.actor}</small>}</dd></div>})}</dl><small>Saved {new Date(record.communications.recorded_at).toLocaleString()} · Notice {record.communications.notice_version}. Automated guest messages are not active.</small></section>}<div className="pilot-actions"><button type="button" className="secondary" disabled={busy||disabled} onClick={()=>void run('staff_read')}>Refresh details</button>{!record?.submitted_at&&<button type="button" className="secondary" disabled={busy||disabled} onClick={()=>void run('staff_issue')}>{record?'Replace link':'Create guest link'}</button>}{record&&record.expires_at>0&&<button type="button" className="text-button" disabled={busy||disabled} onClick={()=>void run('staff_revoke')}>Disable link</button>}</div>{link&&<label className="field">Private guest link<input readOnly value={link} onFocus={e=>e.target.select()}/><button type="button" className="secondary" onClick={async()=>{try{await navigator.clipboard.writeText(link);setCopied(true)}catch{setError('Select and copy the link above.')}}}>{copied?'Copied':'Copy link'}</button><button type="button" className="secondary" onClick={()=>void copyKioskLink()}>Copy shared-tablet kiosk link</button></label>}<PrepareTestPayment actor={actor} canCancel={canCancelPayment} tenant={tenant} property={property} reservation={reservation} disabled={disabled||busy}/><p className="muted">Links expire after 24 hours. Replacing a link disables the previous arrival form. Disabling or replacing an arrival link does not cancel a Stripe test checkout already opened; review that session in Stripe. Share only with the intended guest. This form collects guest-approved contact details; payment and final check-in remain with staff. Kiosk links remain private and reservation-specific; the shared tablet returns to a blank welcome screen when the guest finishes.</p></section>
}
